<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { businessApi } from '../business'
type Policy = { version: number; timeWeight: number; distanceWeight: number; fuelWeight: number; speedLimitKmh: number; matchingDistanceKm: number; deviationDistanceKm: number; deviationConsecutivePoints: number; deviationDurationSeconds: number }
const policy = ref<Policy | null>(null), error = ref(''), notice = ref(''), busy = ref(false)
async function load() { try { policy.value = await businessApi('/policy') } catch (e) { error.value = e instanceof Error ? e.message : '读取失败。' } }
async function save() { if (!policy.value || busy.value) return; busy.value = true; error.value = ''; notice.value = ''; try { policy.value = await businessApi('/policy', policy.value); notice.value = '配置已保存。新模拟运行与新评分使用此版本，既有结果保留原配置快照。' } catch (e) { error.value = e instanceof Error ? e.message : '保存失败。' } finally { busy.value = false } }
onMounted(load)
</script>
<template><section class="section"><div class="section-title"><div><p class="kicker">SCORING AND DETECTION POLICY</p><h2>评分与异常配置</h2></div><button class="outline-button" @click="load">刷新配置</button></div><p class="source-note">权重为 0–1 小数，合计必须为 1。默认耗时 40%、里程 30%、油耗 30%；同值指标为 50 分。新运行保存配置版本与阈值，修改配置不会改写历史评分。</p><p v-if="error" class="alert error" role="alert">{{ error }}</p><p v-if="notice" class="alert success" role="status">{{ notice }}</p><form v-if="policy" class="business-form form-grid" @submit.prevent="save"><h3>当前配置 v{{ policy.version }}</h3><label>耗时权重<input v-model.number="policy.timeWeight" type="number" min="0" max="1" step="0.01" required></label><label>里程权重<input v-model.number="policy.distanceWeight" type="number" min="0" max="1" step="0.01" required></label><label>油耗权重<input v-model.number="policy.fuelWeight" type="number" min="0" max="1" step="0.01" required></label><label>超速阈值（km/h）<input v-model.number="policy.speedLimitKmh" type="number" min="10" max="150" required></label><label>道路匹配距离（km）<input v-model.number="policy.matchingDistanceKm" type="number" min="0.01" max="0.3" step="0.01" required></label><label>持续偏离距离（km）<input v-model.number="policy.deviationDistanceKm" type="number" min="0.01" max="5" step="0.01" required></label><label>偏离连续点数<input v-model.number="policy.deviationConsecutivePoints" type="number" min="2" max="20" required></label><label>偏离持续秒数<input v-model.number="policy.deviationDurationSeconds" type="number" min="1" max="600" required></label><button class="primary-button" :disabled="busy" type="submit">{{ busy ? '保存中…' : '保存新配置版本' }}</button></form></section></template>
